package com.andye.warmod.warhead;import com.andye.warmod.entity.IncomingWarheadEntity;import java.util.*;import net.minecraft.server.level.ServerLevel;public final class IncomingWarheadRegistry{private static final Map<ServerLevel,Map<UUID,IncomingWarheadEntity>> ACTIVE=new WeakHashMap<>();private IncomingWarheadRegistry(){}public static synchronized void register(ServerLevel l,IncomingWarheadEntity e){if(e.radarRootTrackId()!=null&&!e.isRemoved())ACTIVE.computeIfAbsent(l,x->new HashMap<>()).put(e.radarRootTrackId(),e);}public static synchronized Optional<IncomingWarheadEntity> get(ServerLevel l,UUID root){Map<UUID,IncomingWarheadEntity> m=ACTIVE.get(l);if(m==null)return Optional.empty();IncomingWarheadEntity e=m.get(root);if(e==null||e.isRemoved()){m.remove(root);return Optional.empty();}return Optional.of(e);}public static synchronized void unregister(ServerLevel l,UUID root){Map<UUID,IncomingWarheadEntity> m=ACTIVE.get(l);if(m!=null){m.remove(root);if(m.isEmpty())ACTIVE.remove(l);}}public static synchronized void clearAll(){ACTIVE.clear();}}